div.script:
(function(){
 const u=document.getElementById('u'),g=document.getElementById('go'),v=document.getElementById('v'),s=document.getElementById('s');
 function open(){let x=u.value.trim();if(!x)return;if(!/^https?:\/\//i.test(x))x='https://'+x;const target='https://api.allorigins.win/raw?url='+encodeURIComponent(x);s.textContent='Loading '+x;fetch(target).then(r=>{if(!r.ok)throw new Error('Fetch failed');return r.text()}).then(html=>{html=html.replace(/<script[\s\S]*?<\/script>/gi,'').replace(/<iframe[\s\S]*?<\/iframe>/gi,'').replace(/<object[\s\S]*?<\/object>/gi,'').replace(/<embed[^>]*>/gi,'');v.srcdoc=html;s.textContent='Loaded';}).catch(e=>{s.textContent='Could not load this site: '+e.message;});}
 g.onclick=open;u.addEventListener('keydown',e=>{if(e.key==='Enter')open()});
})();
